<#
PowerShell alternative to initialize_marketplace.py, scaffold_plugin.py,
validate_marketplace.py, and release_plugin.py.

Usage: ./marketplace-tools.ps1 <initialize|scaffold|validate|release> [options]
#>
[CmdletBinding()]
param(
  [Parameter(Position=0, Mandatory=$true)][ValidateSet('initialize','scaffold','validate','release')][string]$Command,
  [Parameter(ValueFromRemainingArguments=$true)][string[]]$Arguments
)
$ErrorActionPreference = 'Stop'
$NamePattern = '^[a-z0-9]+(?:-[a-z0-9]+)*$'
$SemVerPattern = '^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$'
$Specs = @{
  claude = @{ catalog='.claude-plugin/marketplace.json'; package='plugins/claude-{0}'; manifest='.claude-plugin/plugin.json'; marketplaceVersion=@('version') }
  openai = @{ catalog='.agents/plugins/marketplace.json'; package='plugins/openai-{0}'; manifest='.codex-plugin/plugin.json'; marketplaceVersion=$null }
  github = @{ catalog='.github/plugin/marketplace.json'; package='plugins/{0}'; manifest='plugin.json'; marketplaceVersion=@('metadata','version') }
}
function Fail([string]$message) { throw "error: $message" }
function Is-Name([string]$value) { $value -match $NamePattern }
function Is-SemVer([string]$value) { $value -match $SemVerPattern }
function Parse-Options([string[]]$tokens) {
  $options=@{}; for($i=0;$i -lt $tokens.Count;$i++) { $token=$tokens[$i]; if($token -in '--allow-existing-files','--require-all-hosts') { $options[$token]=$true; continue }; if(-not $token.StartsWith('--') -or ++$i -ge $tokens.Count) { Fail "invalid option: $token" }; $options[$token]=$tokens[$i] }; $options
}
function Required($options,[string]$name) { if(-not $options.ContainsKey($name) -or [string]::IsNullOrWhiteSpace($options[$name])) { Fail "missing required option: $name" }; [string]$options[$name] }
function Hosts($options) {
  $value = 'claude,openai,github'
  if ($options.ContainsKey('--hosts')) { $value = [string]$options['--hosts'] }
  $values = @($value.Split(',') | ForEach-Object { $_.Trim() } | Where-Object { $_ })
  if (!$values.Count -or @($values | Where-Object { -not $Specs.ContainsKey($_) }).Count -or @($values | Select-Object -Unique).Count -ne $values.Count) { Fail '--hosts must be a unique comma-separated subset of: claude, openai, github' }
  return $values
}
function Read-Json([string]$path) { if(-not (Test-Path -LiteralPath $path -PathType Leaf)) { Fail "Missing JSON file: $path" }; try { Get-Content -LiteralPath $path -Raw | ConvertFrom-Json -AsHashtable } catch { Fail "Invalid JSON in ${path}: $($_.Exception.Message)" } }
function Write-Json([string]$path,$value) { New-Item -ItemType Directory -Force -Path (Split-Path -Parent $path) | Out-Null; $value | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $path -Encoding utf8NoBOM }
function CatalogPath([string]$root,[string]$targetHost) { Join-Path $root $Specs[$targetHost].catalog }
function PackagePath([string]$root,[string]$targetHost,[string]$name) { Join-Path $root ([string]::Format($Specs[$targetHost].package,$name)) }
function ManifestPath([string]$package,[string]$targetHost) { $reusable=Join-Path $package '.github/plugin/plugin.json'; if($targetHost -eq 'github' -and (Test-Path -LiteralPath $reusable -PathType Leaf)) {$reusable} else {Join-Path $package $Specs[$targetHost].manifest} }
function SkillTemplate([string]$name,[string]$description) { "---`nname: $name`ndescription: $description`n---`n`nUse this skill when the user's request matches its description.`n`n1. Identify required inputs and ask one concise question when one is missing.`n2. Follow the smallest safe workflow that completes the requested task.`n3. State the result, changed artifacts, and validation performed.`n4. Do not invent tool results, file contents, or external state.`n" }
function Initialize($o) {
  $root=[IO.Path]::GetFullPath((Required $o '--marketplace')); $name=Required $o '--name'; $description=Required $o '--description'; $author=Required $o '--author'; $version=if($o.ContainsKey('--version')){$o['--version']}else{'1.0.0'}; $targetHosts=Hosts $o
  if(-not(Is-Name $name)){Fail '--name must be lowercase kebab-case'}; if([string]::IsNullOrWhiteSpace($description)-or [string]::IsNullOrWhiteSpace($author)){Fail '--description and --author cannot be empty'}; if(-not(Is-SemVer $version)){Fail '--version must be a Semantic Version such as 1.2.3 or 1.2.3-rc.1'}
  if((Test-Path -LiteralPath $root)-and -not(Test-Path -LiteralPath $root -PathType Container)){Fail "--marketplace must be a directory: $root"}; $existingCatalogs=@($targetHosts|%{CatalogPath $root $_}|?{Test-Path -LiteralPath $_}); if($existingCatalogs.Count){Fail "Refusing to overwrite existing host catalog(s): $($existingCatalogs -join ', ')"}; $entries=if(Test-Path -LiteralPath $root){@(Get-ChildItem -Force -LiteralPath $root)}else{@()}; if($entries.Count -and -not $o.ContainsKey('--allow-existing-files')){Fail "Target contains existing entries; rerun with --allow-existing-files only after user confirmation: $($entries.FullName -join ', ')"}
  New-Item -ItemType Directory -Force -Path (Join-Path $root 'plugins')|Out-Null; foreach($targetHost in $targetHosts){$catalog=switch($targetHost){'claude'{@{name=$name;owner=@{name=$author.Trim()};description=$description;version=$version;plugins=@()}}'openai'{@{name=$name;interface=@{displayName=(Get-Culture).TextInfo.ToTitleCase($name.Replace('-',' '))};plugins=@()}}'github'{@{name=$name;owner=@{name=$author.Trim()};metadata=@{description=$description;version=$version};plugins=@()}}};Write-Json (CatalogPath $root $targetHost) $catalog}; "Initialized '$name' for: $($targetHosts -join ', ')"; 'Create plugins with marketplace-tools.ps1 scaffold, then run marketplace-tools.ps1 validate.'
}
function Scaffold($o) {
  $root=[IO.Path]::GetFullPath((Required $o '--marketplace')); $name=Required $o '--name'; $skill=Required $o '--skill'; $description=Required $o '--description'; $author=Required $o '--author'; $version=if($o.ContainsKey('--version')){$o['--version']}else{'1.0.0'}; $targetHosts=Hosts $o
  if(-not(Is-Name $name)){Fail '--name must be lowercase kebab-case'};if(-not(Is-Name $skill)){Fail '--skill must be lowercase kebab-case'};if([string]::IsNullOrWhiteSpace($description)-or [string]::IsNullOrWhiteSpace($author)){Fail '--description and --author cannot be empty'};if(-not(Is-SemVer $version)){Fail '--version must be a Semantic Version such as 1.2.3 or 1.2.3-rc.1'}
  $catalogs=@{};$data=@{};$packages=@{};foreach($targetHost in $targetHosts){$catalogs[$targetHost]=CatalogPath $root $targetHost;$data[$targetHost]=Read-Json $catalogs[$targetHost];if(-not($data[$targetHost].plugins -is [array])){Fail "Catalog must contain a plugins array: $($catalogs[$targetHost])"};$packages[$targetHost]=PackagePath $root $targetHost $name;if(Test-Path -LiteralPath $packages[$targetHost]){Fail "Refusing to overwrite existing package: $($packages[$targetHost])"};if(@($data[$targetHost].plugins|?{$_.name -eq $name}).Count){Fail "Refusing to overwrite $targetHost catalog entry: $name"}}
  $shared=Join-Path $root "skills/$skill";if($targetHosts -contains 'github' -and(Test-Path -LiteralPath $shared)){Fail "Refusing to overwrite reusable GitHub skill: $shared"};foreach($targetHost in $targetHosts){$package=$packages[$targetHost];$skillPath=if($targetHost -eq 'github'){Join-Path $shared 'SKILL.md'}else{Join-Path $package "skills/$skill/SKILL.md"};New-Item -ItemType Directory -Force -Path (Split-Path -Parent $skillPath)|Out-Null;Set-Content -LiteralPath $skillPath -Encoding utf8NoBOM -Value (SkillTemplate $skill $description);$manifest=@{name=$name;description=$description;version=$version;author=@{name=$author.Trim()};license='MIT';keywords=@('agent-plugin')};if($targetHost -eq 'openai'){$manifest.skills='./skills/';$manifest.interface=@{displayName=(Get-Culture).TextInfo.ToTitleCase($name.Replace('-',' '));shortDescription=$description;longDescription=$description;developerName=$author;category='Productivity';capabilities=@('Read')}};if($targetHost -eq 'github'){$manifest.skills=@("./skills/$skill/")};if($targetHost -eq 'github'){$manifestPath=Join-Path $package '.github/plugin/plugin.json'}else{$manifestPath=Join-Path $package $Specs[$targetHost].manifest};Write-Json $manifestPath $manifest;$source="./$([string]::Format($Specs[$targetHost].package,$name))";$entry=if($targetHost -eq 'openai'){@{name=$name;source=@{source='local';path=$source};policy=@{installation='AVAILABLE';authentication='ON_INSTALL'};category='Productivity'}}else{@{name=$name;source=$source;description=$description;version=$version;author=@{name=$author.Trim()};license='MIT';keywords=@('agent-plugin')}};$data[$targetHost].plugins+= $entry;Write-Json $catalogs[$targetHost] $data[$targetHost]};"Created '$name' for: $($targetHosts -join ', ')";'Replace the generated skill instructions, then run marketplace-tools.ps1 validate.'
}
function Test-Skill([string]$path,[Collections.Generic.List[string]]$errors){$text=Get-Content -LiteralPath $path -Raw;if(-not$text.StartsWith("---`n")){$errors.Add("${path}: SKILL.md must begin with YAML frontmatter");return};$end=$text.IndexOf("`n---`n",4);if($end -lt 0){$errors.Add("${path}: SKILL.md frontmatter is not terminated");return};$head=$text.Substring(4,$end-4);$name=([regex]::Match($head,'(?m)^name:\s*(.+)$')).Groups[1].Value.Trim();$description=([regex]::Match($head,'(?m)^description:\s*(.+)$')).Groups[1].Value.Trim();if(-not(Is-Name $name)){$errors.Add("${path}: frontmatter needs a non-empty kebab-case name")};if([string]::IsNullOrWhiteSpace($description)){$errors.Add("${path}: frontmatter needs a non-empty description")}}
function Validate($o) {
  $root=[IO.Path]::GetFullPath((Required $o '--marketplace'));$plugin=if($o.ContainsKey('--plugin')){$o['--plugin']}else{$null};$targetHosts=Hosts $o;if($plugin -and -not(Is-Name $plugin)){Fail '--plugin must be lowercase kebab-case'};$errors=[Collections.Generic.List[string]]::new();$versions=@{};$checked=[Collections.Generic.List[string]]::new()
  foreach($targetHost in $targetHosts){$catalogPath=CatalogPath $root $targetHost;try{$catalog=Read-Json $catalogPath}catch{$errors.Add($_.Exception.Message.Replace('error: ',''));continue};if(-not($catalog.plugins -is [array])){$errors.Add("${catalogPath}: plugins must be an array");continue};$entries=@{};foreach($entry in $catalog.plugins){if(-not($entry -is [hashtable])-or -not(Is-Name ([string]$entry.name))){$errors.Add("${catalogPath}: every plugin entry needs a kebab-case name");continue};if($entries.ContainsKey($entry.name)){$errors.Add("${catalogPath}: duplicate plugin entry '$($entry.name)'");continue};$entries[$entry.name]=$entry};$names=if($plugin){@($plugin)}else{@($entries.Keys)};foreach($name in $names){if(-not$entries.ContainsKey($name)){if($plugin-and$o.ContainsKey('--require-all-hosts')){$errors.Add("Plugin '$plugin' is missing from: $targetHost")};continue};$entry=$entries[$name];$source=if($targetHost -eq 'openai'){if(-not($entry.source -is [hashtable])-or $entry.source.source -ne 'local'){$errors.Add("$targetHost catalog '$name': only OpenAI target-path sources can be validated");continue};$entry.source.path}else{$entry.source};if(-not($source -is [string])-or -not$source.StartsWith('./')){$errors.Add("$targetHost catalog '$name': source must be a ./ path");continue};$package=[IO.Path]::GetFullPath((Join-Path $root $source.Substring(2)));if(-not$package.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){$errors.Add("$targetHost catalog '$name': source escapes the marketplace root");continue};$manifestPath=ManifestPath $package $targetHost;try{$manifest=Read-Json $manifestPath}catch{$errors.Add($_.Exception.Message.Replace('error: ',''));continue};if($manifest.name -ne $name){$errors.Add("${manifestPath}: name must equal catalog entry '$name'")};if(-not(Is-SemVer ([string]$manifest.version))){$errors.Add("${manifestPath}: version must be a Semantic Version")}elseif($targetHost -ne 'openai' -and ((-not(Is-SemVer ([string]$entry.version)))-or $entry.version -ne $manifest.version)){$errors.Add("$targetHost catalog '$name': version must equal $manifestPath")};if([string]::IsNullOrWhiteSpace([string]$manifest.description)){$errors.Add("${manifestPath}: description must be a non-empty string")};$skills=@();$reusable=Join-Path $package '.github/plugin/plugin.json';if($targetHost -eq 'github'-and$manifestPath-eq$reusable){$paths=@($manifest.skills);if(-not$paths.Count){$errors.Add("${manifestPath}: reusable GitHub plugin needs a non-empty skills array")};foreach($relative in $paths){if(-not($relative-is[string])-or-not$relative.StartsWith('./')){$errors.Add("${manifestPath}: reusable skill paths must start with ./");continue};$skillRoot=Join-Path $root $relative.Substring(2);if(Test-Path -LiteralPath $skillRoot -PathType Container){$skills+=Get-ChildItem -LiteralPath $skillRoot -Recurse -Filter SKILL.md}elseif(Test-Path -LiteralPath $skillRoot -PathType Leaf){$skills+=Get-Item -LiteralPath $skillRoot}else{$errors.Add("${manifestPath}: reusable skill path does not exist: $relative")}}}else{$skillRoot=Join-Path $package 'skills';if(Test-Path -LiteralPath $skillRoot -PathType Container){$skills=@(Get-ChildItem -LiteralPath $skillRoot -Recurse -Filter SKILL.md)}};if(-not$skills.Count){$errors.Add("${package}: must include at least one skills/*/SKILL.md")};foreach($file in $skills){Test-Skill $file.FullName $errors};if(-not$versions.ContainsKey($name)){$versions[$name]=@{}};$versions[$name][$targetHost]=$manifest.version;$checked.Add("${targetHost}:$name")}}
  if($plugin-and$o.ContainsKey('--require-all-hosts')-and$versions.ContainsKey($plugin)-and@($versions[$plugin].Values|select -Unique).Count-gt1){$errors.Add("Plugin '$plugin' must use one version across selected hosts")};if($errors.Count){[Console]::Error.WriteLine('Marketplace validation failed:');$errors|%{[Console]::Error.WriteLine("- $_")};exit 1};"Marketplace validation passed: $(if($checked.Count){$checked-join', '}else{'no plugins'})"
}
function Release($o){$root=[IO.Path]::GetFullPath((Required $o '--marketplace'));$plugin=Required $o '--plugin';$version=Required $o '--version';$marketplaceVersion=if($o.ContainsKey('--marketplace-version')){$o['--marketplace-version']}else{$null};$targetHosts=Hosts $o;if(-not(Is-Name $plugin)){Fail '--plugin must be lowercase kebab-case'};if(-not(Is-SemVer $version)){Fail '--version must be a Semantic Version such as 1.2.3 or 1.2.3-rc.1'};if($marketplaceVersion-and-not(Is-SemVer $marketplaceVersion)){Fail '--marketplace-version must be a Semantic Version'};$releases=@();$current=@();foreach($targetHost in $targetHosts){$catalogPath=CatalogPath $root $targetHost;$catalog=Read-Json $catalogPath;$entry=@($catalog.plugins|?{$_.name-eq$plugin});if($entry.Count-ne1){Fail "Catalog must contain exactly one '$plugin' entry: $catalogPath"};$manifestPath=ManifestPath (PackagePath $root $targetHost $plugin) $targetHost;$manifest=Read-Json $manifestPath;if($manifest.name-ne$plugin){Fail "${manifestPath}: name must equal '$plugin'"};if(-not(Is-SemVer ([string]$manifest.version))){Fail "${manifestPath}: version must be a Semantic Version"};if($targetHost-ne'openai'-and$entry[0].version-ne$manifest.version){Fail "${catalogPath}: '$plugin' version must match $manifestPath"};$current+=$manifest.version;$releases+=@{host=$targetHost;catalogPath=$catalogPath;catalog=$catalog;entry=$entry[0];manifestPath=$manifestPath;manifest=$manifest}};if(@($current|select -Unique).Count-ne1){Fail 'Selected host packages must share one current plugin version before release'};if($current[0]-eq$version){Fail '--version must differ from the current plugin version'};foreach($release in $releases){$release.manifest.version=$version;if($release.host-ne'openai'){$release.entry.version=$version};if($marketplaceVersion-and$Specs[$release.host].marketplaceVersion){$value=$release.catalog;foreach($key in $Specs[$release.host].marketplaceVersion[0..($Specs[$release.host].marketplaceVersion.Count-2)]){if(-not$value.ContainsKey($key)){$value[$key]=@{}};$value=$value[$key]};$value[$Specs[$release.host].marketplaceVersion[-1]]=$marketplaceVersion};Write-Json $release.manifestPath $release.manifest;Write-Json $release.catalogPath $release.catalog};"Released '$plugin' $version for: $($targetHosts-join', ')";if($marketplaceVersion){"Updated supported marketplace catalog versions to $marketplaceVersion"};'Create an immutable Git tag and publish the intended release channel after validation.'}
try {$o=Parse-Options $Arguments;switch($Command){'initialize'{Initialize $o};'scaffold'{Scaffold $o};'validate'{Validate $o};'release'{Release $o}}}catch{[Console]::Error.WriteLine($_.Exception.Message);exit 2}
